mapper.select:
SELECT a.id, a.title, a.summary, a.category_id, a.author_id, a.status, a.audit_remark, a.publish_time, a.view_count, a.version, a.create_time, a.update_time, c.name AS category_name, u.nickname AS author_name, r.status AS revision_status FROM cms_article a LEFT JOIN cms_category c ON c.id = a.category_id LEFT JOIN sys_user u ON u.id = a.author_id LEFT JOIN cms_article_revision r ON r.article_id = a.id WHERE a.deleted = 0
AND a.title LIKE CONCAT('%', #{q.title}, '%')
AND a.category_id IN
#{categoryId}
AND a.status = #{q.status}
AND a.author_id = #{q.authorId}
AND a.create_time >= #{q.startTime}
AND a.create_time < #{q.endTime}
ORDER BY
a.title a.publish_time a.view_count a.update_time a.create_time
ASC DESC
, a.id DESC
